    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    const name = this.nameInput().trim();
    const from = this.fromInput().trim() || this.session.today() || '';
    const to = this.toInput().trim();
    if (!/^\S+$/.test(name)) {
